import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u04")

L(1, "O alfabeto", "Os nomes das letras e como soletrar.",
  ["Dizer os nomes das letras", "Pedir e dar a soletração de uma palavra"],
  vocab=[V("v-letter","letter","letra","noun","de","letters"), V("v-woord","woord","palavra","noun","het","woorden"),
         V("v-spellen","spellen","soletrar","verb",note="ik spel, jij spelt"), V("v-schrijven","schrijven","escrever","verb",note="ik schrijf, jij schrijft"),
         V("v-alfabet","alfabet","alfabeto","noun","het")],
  ex=[("Hoe spel je dat?","Como se soletra isso?"),("Hoe schrijf je dat?","Como se escreve isso?"),("Es, ie, el, vee, aa.","S, I, L, V, A.")],
  gram=[G("g-alfabeto","Os nomes das letras","Vogais: **aa, ee, ie, oo, uu**. Algumas letras confundem: **g** = «gee» (com o som gutural), **h** = «haa», **j** = «jee» (≈ «iê»), **v** = «vee», **w** = «wee», **y** = «ij» (ou «griekse ij»), **z** = «zet», **q** = «kuu». A combinação **ij** soletra-se também «lange ij».",
    [("A — aa","a"),("J — jee","jota"),("Z — zet","zê")],
    "O «e» neerlandês soletra-se «ee» e o «i» soletra-se «ie»: o oposto do que um português espera.")],
  review=["v-hoe","v-naam","v-mijn"],
  exs=[
    MC("Como se diz a letra J?", ["*jee","zjee|O «j» neerlandês soa como «i».","ji|Não: o nome da letra é «jee»."], "J = «jee», que soa aproximadamente «iê».", ["v-letter"]),
    MC("Como se soletra a letra I?", ["*ie","ee|«ee» é o nome da letra E.","ij|«ij» é o nome do Y."], "As letras E e I trocam-nos as voltas: E = «ee», I = «ie».", ["v-letter"]),
    MA([("haa","H"),("jee","J"),("wee","W"),("zet","Z")], "Nomes de letras que diferem do português.", ["v-letter"]),
    LI("Hoe spel je dat?", ["Hoe spel je dat"], "Como se soletra isso?", "«spel» com «e» curto; «je» sem acento.", ["v-spellen"]),
    CJ("spellen","jij","Hoe ___ je dat?", ["spel"], "Na pergunta, «je» vem depois do verbo e o -t cai: hoe spel je…?", ["v-spellen"]),
    TR("nl-pt","Hoe schrijf je dat?", ["Como se escreve isso","Como (é que )escreves isso"], "«Hoe schrijf je…?» usa «je» genérico, como o nosso «se»: como se escreve?", ["v-schrijven"]),
    DL([("Rececionista","Hoe spelt u uw naam?","Como soletra o seu nome?"),("Ana","")], ["*Es, ie, el, vee, aa.","Ik heet Silva.|Já sabem o nome; pedem que o soletre.","Silva, alstublieft.|É preciso dizer as letras uma a uma."], "Soletrar = dizer o nome de cada letra.", ["v-spellen"]),
    AR("woord","a palavra","het", "«Het woord» — plural «woorden».", ["v-woord"]),
    AR("letter","a letra","de", "«De letter».", ["v-letter"]),
    FB("Hoe ___ je «fiets»?", ["schrijf","spel"], "«Hoe schrijf je…?» ou «Hoe spel je…?».", ["v-schrijven"], choices=["schrijf","lach","ga"], tr="Como se escreve «fiets»?"),
  ], diff=1, mins=5)

L(2, "Sílabas e plurais", "Porque é que «maan» dá «manen» e «man» dá «mannen».",
  ["Formar plurais regulares em -en", "Perceber quando se dobra ou se simplifica a vogal"],
  vocab=[V("v-boom","boom","árvore","noun","de","bomen"), V("v-straat","straat","rua","noun","de","straten"),
         V("v-pen","pen","caneta","noun","de","pennen"), V("v-raam","raam","janela","noun","het","ramen"),
         V("v-kop","kop","chávena","noun","de","koppen",note="een kop koffie = uma chávena de café"),
         V("v-zijn-plural","zijn","são|estão","verb",note="Forma de «zijn» para o plural: de bomen zijn groot.")],
  ex=[("de boom — de bomen","a árvore — as árvores"),("de pen — de pennen","a caneta — as canetas"),("het raam — de ramen","a janela — as janelas","No plural usa-se sempre «de».")],
  gram=[G("g-plural-en","Plural em -en e ortografia","O plural mais comum faz-se com **-en**. Uma vogal longa escrita em dobro (**maan**) fica simples quando a sílaba passa a acabar em vogal: **ma-nen**. Uma vogal curta (**man**) obriga a dobrar a consoante para continuar curta: **man-nen**. No plural, o artigo é **sempre de**: het raam → de ramen.",
    [("straat → straten","rua → ruas"),("bed → bedden","cama → camas")],
    "Em português o plural muda pouco a escrita; em neerlandês a ortografia ajusta-se para manter o som da vogal."),
   ],
  review=["v-maan","v-man","v-bed","v-boek","v-groot","v-oud"],
  exs=[
    MC("Qual é o plural de «maan» (lua)?", ["*manen","maanen|Na sílaba aberta «ma-» a vogal já é longa com uma só letra.","mannen|«mannen» é o plural de «man» (homem)."], "maan → ma-nen: a sílaba «ma» termina em vogal, por isso basta um «a».", ["v-maan"]),
    MC("Qual é o plural de «pen» (caneta)?", ["*pennen","penen|Assim o «e» ficaria longo.","pens|Este plural não existe."], "Vogal curta: dobra-se a consoante (pen-nen).", ["v-pen"]),
    MA([("boom","árvore"),("straat","rua"),("pen","caneta"),("raam","janela")], "Palavras desta lição.", ["v-boom","v-straat","v-pen","v-raam"]),
    AR("raam","a janela","het", "«Het raam», mas no plural «de ramen».", ["v-raam"]),
    MC("Qual é o artigo de «ramen» (janelas)?", ["*de","het|No plural nunca se usa «het»."], "Todos os plurais levam «de».", ["v-raam"]),
    TR("pt-nl","as ruas", ["de straten"], "straat → stra-ten; plural com «de».", ["v-straat"]),
    FE(["De","straaten","zijn","oud."], 1, "straten", "Na sílaba aberta «stra-» o «a» longo escreve-se com uma só letra.", ["v-straat","v-zijn-plural"]),
    WO("As árvores são grandes.", ["De","bomen","zijn","groot"], "Plural: «de bomen zijn…».", ["v-boom","v-zijn-plural","v-groot"]),
    LI("de ramen", ["de ramen"], "as janelas", "Um só «a», mas longo: ra-men.", ["v-raam"]),
    TR("nl-pt","Een kop koffie, alstublieft.", ["Uma chávena de café, por favor","Um café, por favor"], "«een kop koffie» = uma chávena de café.", ["v-kop","v-koffie"]),
  ], diff=2, mins=6)

L(3, "Palavras compostas e acento", "Juntar palavras e saber que artigo usar.",
  ["Reconhecer palavras compostas", "Escolher o artigo de uma palavra composta pela última parte"],
  vocab=[V("v-fietspad","fietspad","ciclovia","noun","het","fietspaden"), V("v-voetbal","voetbal","futebol","noun","het"),
         V("v-ziekenhuis","ziekenhuis","hospital","noun","het","ziekenhuizen"), V("v-station","station","estação","noun","het","stations",note="Acento na 2.ª sílaba: sta-TION."),
         V("v-supermarkt","supermarkt","supermercado","noun","de","supermarkten"), V("v-koelkast","koelkast","frigorífico","noun","de","koelkasten")],
  ex=[("het fiets + het pad = het fietspad","a ciclovia"),("de koel + de kast = de koelkast","o frigorífico"),("Waar is het station?","Onde é a estação?")],
  gram=[G("g-compostas","Palavras compostas","O neerlandês junta palavras numa só: **fiets + pad = fietspad**. O acento cai normalmente na **primeira parte** (*FIETSpad*) e o **artigo é o da última parte**: het huis → **het** ziekenhuis; de kast → **de** koelkast.",
    [("het ziekenhuis","o hospital"),("de supermarkt","o supermercado")],
    "Em português a palavra principal costuma vir primeiro («casa de banho»); em neerlandês vem no fim.")],
  review=["v-huis","v-fiets","v-waar","v-gaan"],
  exs=[
    AR("ziekenhuis","o hospital","het", "A última parte é «huis», que usa «het».", ["v-ziekenhuis"]),
    AR("koelkast","o frigorífico","de", "A última parte, «kast» (armário), usa «de».", ["v-koelkast"]),
    AR("fietspad","a ciclovia","het", "«Het pad» (o caminho) → het fietspad.", ["v-fietspad"]),
    MC("Porque se diz «het ziekenhuis»?", ["*Porque a última parte, «huis», usa «het»","Porque todas as palavras longas usam «het»|Não existe essa regra.","Porque «zieken» usa «het»|Conta a última parte, não a primeira."], "Nas compostas, o artigo vem da última palavra.", ["v-ziekenhuis"]),
    MA([("ziekenhuis","hospital"),("supermarkt","supermercado"),("voetbal","futebol"),("koelkast","frigorífico")], "Compostas frequentes.", ["v-ziekenhuis","v-supermarkt","v-voetbal","v-koelkast"]),
    LI("Waar is het station?", ["Waar is het station"], "Onde é a estação?", "«station» é uma exceção: acento na segunda sílaba.", ["v-station"]),
    TR("pt-nl","Onde é o hospital?", ["Waar is het ziekenhuis"], "Waar + is + sujeito.", ["v-ziekenhuis","v-waar"]),
    FB("Ik ga naar de ___.", ["supermarkt"], "«Naar de supermarkt gaan» = ir ao supermercado.", ["v-supermarkt"], choices=["supermarkt","ziekenhuis","fietspad"], tr="Vou ao supermercado."),
    TR("nl-pt","Het fietspad is rood.", ["A ciclovia é vermelha"], "Muitas ciclovias nos Países Baixos têm piso vermelho.", ["v-fietspad","v-rood"]),
    WO("Vou de bicicleta para a estação.", ["Ik","ga","met","de","fiets","naar","het","station"], "«met de fiets» = de bicicleta; «naar» = para.", ["v-station","v-fiets"]),
  ], diff=2, mins=6)

L(4, "Não percebi!", "Pedir para repetir, falar devagar ou explicar uma palavra.",
  ["Dizer que não percebeu", "Pedir para repetir ou falar mais devagar", "Perguntar o que significa uma palavra"],
  vocab=[V("v-begrijpen","begrijpen","perceber|compreender","verb",note="ik begrijp, jij begrijpt"),
         V("v-niet","niet","não","adverb",note="Nega verbos e adjetivos: ik begrijp het niet."),
         V("v-herhalen","herhalen","repetir","verb"), V("v-langzaam","langzaam","devagar","adverb"),
         V("v-betekenen","betekenen","significar","verb",note="Wat betekent…? = O que significa…?"),
         V("v-zeggen","zeggen","dizer","verb",note="ik zeg, jij zegt"), V("v-nederlands","Nederlands","neerlandês","noun","het",note="A língua. «in het Nederlands» = em neerlandês.")],
  ex=[("Sorry, ik begrijp het niet.","Desculpe, não percebo."),("Kunt u dat herhalen?","Pode repetir?"),("Wat betekent «gezellig»?","O que significa «gezellig»?"),("Hoe zeg je «obrigado» in het Nederlands?","Como se diz «obrigado» em neerlandês?")],
  gram=[G("g-frases-sobrevivencia","Frases de sobrevivência","Guarde estas frases como blocos: **Ik begrijp het niet** (não percebo), **Kunt u dat herhalen?** (pode repetir?), **Langzaam, alstublieft** (devagar, por favor), **Wat betekent…?** (o que significa…?). Repare que **niet** vem no fim: *ik begrijp het niet*.",
    [("Ik begrijp het niet.","Não percebo."),("Kun je dat herhalen?","Podes repetir? (informal)")],
    "Em português o «não» vem antes do verbo; em neerlandês, «niet» vai muitas vezes para o fim da frase.")],
  review=["v-sorry","v-wat","v-hoe"],
  exs=[
    MC("Não percebeu o que lhe disseram. O que diz?", ["*Sorry, ik begrijp het niet.","Graag gedaan.|Isso é «de nada».","Ik heet het niet.|«heten» = chamar-se."], "«Ik begrijp het niet» = não percebo.", ["v-begrijpen","v-niet"]),
    EX("Kunt u dat herhalen?", "Pode o senhor isso repetir?", "Quando se usa esta frase?", ["*Para pedir a alguém que repita","Para pedir desculpa|Isso seria «sorry».","Para agradecer|Isso seria «dank u wel»."], "Forma educada (u). Informal: «Kun je dat herhalen?».", ["v-herhalen"]),
    LI("Ik begrijp het niet.", ["Ik begrijp het niet"], "Não percebo.", "«ij» em «begrijp» soa como «ei».", ["v-begrijpen","v-niet"]),
    WO("Não percebo.", ["Ik","begrijp","het","niet"], "«niet» vai para o fim.", ["v-begrijpen","v-niet"]),
    TR("nl-pt","Wat betekent «fiets»?", ["O que [significa|quer dizer] «fiets»"], "«Wat betekent…?» serve para perguntar o sentido de uma palavra.", ["v-betekenen","v-wat"]),
    TR("pt-nl","Devagar, por favor.", ["Langzaam(,) [alstublieft|alsjeblieft]"], "«Langzaam» = devagar.", ["v-langzaam"]),
    FB("Hoe ___ je «obrigado» in het Nederlands?", ["zeg"], "«Hoe zeg je…?» = como se diz…? (o -t cai antes de «je»).", ["v-zeggen","v-nederlands"], choices=["zeg","zegt","zeggen"], tr="Como se diz «obrigado» em neerlandês?"),
    CJ("zeggen","jij","Jij ___ «dank je wel».", ["zegt"], "zeggen: ik zeg, jij zegt.", ["v-zeggen"]),
    DL([("Funcionário","U moet dit formulier invullen.","Tem de preencher este formulário."),("Ana",""),("Funcionário","U moet dit formulier invullen.","Tem de preencher este formulário.")], ["*Sorry, kunt u dat herhalen?","Dank u wel, tot ziens!|O funcionário repete a frase: a Ana pediu-lhe isso.","Ik kom uit Portugal.|Não responde à situação."], "Pedir para repetir é perfeitamente normal.", ["v-herhalen"]),
    SW("Peça a alguém, educadamente, que fale mais devagar e repita.", ["[Sorry|Pardon](,) kunt u dat herhalen(?) [Langzaam|Langzamer](,) [alstublieft|alsjeblieft]","Langzaam(,) alstublieft(.) Kunt u dat herhalen"],
       ["Usa «kunt u…?» ou «kun je…?»","Usa «herhalen»","Pede «langzaam» e diz «alstublieft»"], 4, "Modelo: «Sorry, kunt u dat herhalen? Langzaam, alstublieft.»", ["v-herhalen","v-langzaam"]),
  ], diff=2, mins=6)

L(5, "Ler e soletrar", "Revisão da unidade: letras, plurais, compostas e frases de sobrevivência.",
  ["Aplicar as regras de leitura a palavras novas", "Usar as frases de sobrevivência numa conversa"],
  ex=[("Hoe spel je «straat»? — Es, tee, er, aa, aa, tee.","Como se soletra «straat»?")],
  review=["v-spellen","v-straat","v-ziekenhuis","v-begrijpen","v-herhalen","v-langzaam","v-boom","v-raam"],
  exs=[
    MC("Qual é o plural de «boom»?", ["*bomen","boomen|Na sílaba aberta basta um «o».","bommen|Assim o «o» seria curto."], "boom → bo-men.", ["v-boom"]),
    MC("Qual é o artigo de «supermarkt»?", ["*de","het|A última parte, «markt», usa «de»."], "de markt → de supermarkt.", ["v-supermarkt"]),
    MA([("ramen","janelas"),("bomen","árvores"),("straten","ruas"),("woorden","palavras")], "Plurais desta unidade.", ["v-raam","v-boom","v-straat","v-woord"]),
    TR("nl-pt","Kun je dat herhalen?", ["Podes repetir(?)","Podes repetir isso"], "Forma informal de «Kunt u dat herhalen?».", ["v-herhalen"]),
    FE(["Ik","begrijp","niet","het."], 2, "het niet", "A ordem certa é «ik begrijp het niet»: «niet» depois de «het».", ["v-niet"]),
    LI("Langzaam, alstublieft.", ["Langzaam(,) alstublieft"], "Devagar, por favor.", "«aa» longo em «langzaam».", ["v-langzaam"]),
    TR("pt-nl","as canetas e as janelas", ["de pennen en de ramen"], "Plural sempre com «de».", ["v-pen","v-raam"]),
    CO("dialogue","Na biblioteca", "Bibliotecaris: Hoe heet u?\nPedro: Pedro Costa.\nBibliotecaris: Hoe spelt u «Costa»?\nPedro: Cee, oo, es, tee, aa.\nBibliotecaris: Dank u wel!",
       [("O que pede a bibliotecária?", ["*Que soletre o apelido","Que repita o nome mais devagar","Que diga de onde é"]),("Qual é a primeira letra que o Pedro diz?", ["*Cee (C)","Kaa (K)","Es (S)"])],
       "«Hoe spelt u…?» = como soletra…?", ["v-spellen"]),
    SW("Escreva como soletra o seu primeiro nome (ou «Ana»), letra a letra, com os nomes neerlandeses.", ["Aa(,) en(,) aa"], ["Usa os nomes das letras (aa, bee, see…)","Separa as letras com vírgulas"], 2, "Ana = «aa, en, aa». Confirme cada letra com a lista do alfabeto.", ["v-spellen","v-letter"]),
    TR("nl-pt","Wat betekent «koelkast»?", ["O que [significa|quer dizer] «koelkast»"], "«koelkast» = frigorífico (koel = fresco, kast = armário).", ["v-koelkast","v-betekenen"]),
  ], diff=2, mins=6)

W()
